#[derive(Clone, Copy, Debug, PartialEq)]
pub struct IdeApplicationConfig {
    maximum_block_frames: usize,
    project_limits: ProjectPlaybackLimits,
    output_meter_ballistics: SamplePeakBallisticsConfig,
}

// Construction rejects non-finite meter policy values, so the contained f32
// values remain reflexive and the configuration retains value equality.
impl Eq for IdeApplicationConfig {}

impl IdeApplicationConfig {
    /// Creates the fixed 48 kHz desktop application policy.
    ///
    /// # Errors
    ///
    /// Returns [`IdeApplicationConfigError`] when callback capacity is invalid.
    pub fn try_new(
        maximum_block_frames: usize,
        project_limits: ProjectPlaybackLimits,
    ) -> Result<Self, IdeApplicationConfigError> {
        let output = DesktopOutputConfig::try_new(DESKTOP_SAMPLE_RATE_HZ, maximum_block_frames)
            .map_err(IdeApplicationConfigError::Output)?;
        let input = DesktopInputConfig::try_new(DESKTOP_SAMPLE_RATE_HZ, maximum_block_frames)
            .map_err(IdeApplicationConfigError::Input)?;
        DesktopMonitoringConfig::try_new(
            input,
            output,
            DESKTOP_MONITORING_TRANSPORT_FRAMES,
            DESKTOP_MONITORING_TARGET_FRAMES,
            DESKTOP_MONITORING_CHUNK_FRAMES,
        )
        .map_err(IdeApplicationConfigError::Monitoring)?;
        let output_meter_ballistics = SamplePeakBallisticsConfig::try_new(
            DESKTOP_SAMPLE_RATE_HZ,
            IDE_OUTPUT_METER_FLOOR_DBFS,
            IDE_OUTPUT_METER_FALLOFF_DB_PER_SECOND,
            u64::MAX,
        )
        .map_err(IdeApplicationConfigError::OutputMeterBallistics)?;
        Ok(Self {
            maximum_block_frames,
            project_limits,
            output_meter_ballistics,
        })
    }

    #[must_use]
    pub const fn maximum_block_frames(self) -> usize {
        self.maximum_block_frames
    }

    #[must_use]
    pub const fn project_limits(self) -> ProjectPlaybackLimits {
        self.project_limits
    }

    const fn output_meter_ballistics(self) -> SamplePeakBallisticsConfig {
        self.output_meter_ballistics
    }
}

/// One running-session read of the final output meter.
///
/// The raw snapshot remains available for loudness consumers. Separate
/// display snapshots provide bounded final-output and post-fader strip
/// sample-peak presentation without changing audio-engine state.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct IdeOutputMeterObservation {
    latest: LatestOutputMeterSnapshot,
    sample_peak_ballistics: Option<IdeOutputPeakBallisticsSnapshot>,
    mixer_strip_ballistics: Option<IdeMixerStripPeakBallisticsSnapshot>,
    peak_hold_available: bool,
}

impl IdeOutputMeterObservation {
    #[must_use]
    pub const fn empty() -> Self {
        Self {
            latest: LatestOutputMeterSnapshot::empty(),
            sample_peak_ballistics: None,
            mixer_strip_ballistics: None,
            peak_hold_available: false,
        }
    }

    #[must_use]
    pub const fn latest(self) -> LatestOutputMeterSnapshot {
        self.latest
    }

    #[must_use]
    pub const fn sample_peak_ballistics(self) -> Option<IdeOutputPeakBallisticsSnapshot> {
        self.sample_peak_ballistics
    }

    /// Returns newly delivered decaying post-fader strip sample-peak values.
    ///
    /// The values are absent until a raw meter snapshot arrives and do not
    /// become durable project or audio-engine state.
    #[must_use]
    pub const fn mixer_strip_ballistics(self) -> Option<IdeMixerStripPeakBallisticsSnapshot> {
        self.mixer_strip_ballistics
    }

    #[must_use]
    pub const fn peak_hold_available(self) -> bool {
        self.peak_hold_available
    }
}

#[derive(Debug)]
struct IdeOutputMeterObserver {
    ballistics: StereoSamplePeakBallistics,
    strip_ballistics: MixerStripSamplePeakBallistics,
    latest: Option<IdeOutputPeakBallisticsSnapshot>,
    peak_hold_available: bool,
}

impl IdeOutputMeterObserver {
    const fn new(config: SamplePeakBallisticsConfig) -> Self {
        Self {
            ballistics: StereoSamplePeakBallistics::new(config),
            strip_ballistics: MixerStripSamplePeakBallistics::new(config),
            latest: None,
            peak_hold_available: false,
        }
    }

    fn observe(&mut self, receiver: &mut OutputMeterReceiver) -> IdeOutputMeterObservation {
        let read =
            receiver.read_ballistics_with_strips(&mut self.ballistics, &mut self.strip_ballistics);
        let latest = read.latest();
        if latest.sender_disconnected() {
            self.reset();
            return IdeOutputMeterObservation {
                latest,
                sample_peak_ballistics: None,
                mixer_strip_ballistics: None,
                peak_hold_available: false,
            };
        }
        if let Some(snapshot) = read.ballistics() {
            self.latest = Some(snapshot);
            self.peak_hold_available = true;
        }
        IdeOutputMeterObservation {
            latest,
            sample_peak_ballistics: self.latest,
            mixer_strip_ballistics: read.strip_ballistics(),
            peak_hold_available: self.peak_hold_available,
        }
    }

    fn reset(&mut self) {
        self.ballistics.reset();
        self.strip_ballistics.reset();
        self.latest = None;
        self.peak_hold_available = false;
    }

    fn reset_peak_hold(&mut self) -> IdeOutputMeterObservation {
        self.ballistics.reset_peak_hold();
        self.peak_hold_available = false;
        IdeOutputMeterObservation {
            latest: LatestOutputMeterSnapshot::empty(),
            sample_peak_ballistics: self.latest,
            mixer_strip_ballistics: None,
            peak_hold_available: false,
        }
    }
}

/// One running-session read of the raw accepted desktop input meter.
///
/// The raw snapshot describes one validated capture block before cue gain,
/// mute, bridge admission, resampling, or output mixing. The display snapshot
/// is consumer-side sample-peak presentation only; it carries no held peak.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct IdeInputMeterObservation {
    latest: LatestInputMeterSnapshot,
    sample_peak_display: Option<IdeInputPeakDisplaySnapshot>,
}

impl IdeInputMeterObservation {
    #[must_use]
    pub const fn empty() -> Self {
        Self {
            latest: LatestInputMeterSnapshot::empty(),
            sample_peak_display: None,
        }
    }

    #[must_use]
    pub const fn latest(self) -> LatestInputMeterSnapshot {
        self.latest
    }

    /// Returns the persistent decaying stereo sample-peak display while the
    /// matching accepted-input authority remains live.
    #[must_use]
    pub const fn sample_peak_display(self) -> Option<IdeInputPeakDisplaySnapshot> {
        self.sample_peak_display
    }

    /// Builds display-only input evidence for a generated IDE UI test.
    ///
    /// This helper is feature-gated so production callers cannot manufacture
    /// accepted-capture authority.
    ///
    /// # Panics
    ///
    /// Panics if the fixed desktop input-meter display policy is changed to an
    /// invalid sample-peak configuration.
    #[cfg(feature = "ui-test-support")]
    #[must_use]
    pub fn display_for_ui_test(
        left_sample_peak: Option<f32>,
        right_sample_peak: Option<f32>,
    ) -> Self {
        let config = SamplePeakBallisticsConfig::try_new(
            DESKTOP_SAMPLE_RATE_HZ,
            IDE_OUTPUT_METER_FLOOR_DBFS,
            IDE_OUTPUT_METER_FALLOFF_DB_PER_SECOND,
            0,
        )
        .expect("fixed desktop input-meter display policy must remain valid");
        let snapshot = StereoSamplePeakDisplayBallistics::new(config)
            .update(1, 1, left_sample_peak, right_sample_peak)
            .snapshot();
        Self {
            latest: LatestInputMeterSnapshot::empty(),
            sample_peak_display: Some(snapshot),
        }
    }
}

#[derive(Debug)]
struct IdeInputMeterObserver {
    ballistics: StereoSamplePeakDisplayBallistics,
    latest: Option<IdeInputPeakDisplaySnapshot>,
}

impl IdeInputMeterObserver {
    const fn new(config: SamplePeakBallisticsConfig) -> Self {
        Self {
            ballistics: StereoSamplePeakDisplayBallistics::new(config),
            latest: None,
        }
    }

    fn observe(&mut self, receiver: &mut InputMeterReceiver) -> IdeInputMeterObservation {
        let read = receiver.read_display(&mut self.ballistics);
        let latest = read.latest();
        if latest.sender_disconnected() {
            self.reset();
            return IdeInputMeterObservation {
                latest,
                sample_peak_display: None,
            };
        }
        if let Some(snapshot) = read.display() {
            self.latest = Some(snapshot);
        }
        IdeInputMeterObservation {
            latest,
            sample_peak_display: self.latest,
        }
    }

    fn unavailable(&mut self) -> IdeInputMeterObservation {
        self.reset();
        IdeInputMeterObservation::empty()
    }

    fn reset(&mut self) {
        self.ballistics.reset();
        self.latest = None;
    }
}

