#[derive(Debug)]
pub enum IdeNativeFilterEditError {
    InvalidIdentity,
    CopyRequiresDistinctChains,
    TrackUnavailable,
    ChainUnavailable,
    MixerSave(Box<IdeProjectSaveError>),
    Device(DeviceChainError),
    Serialization(DeviceChainError),
    MixerPublication(Box<ProjectResourcePublicationError>),
    Publication {
        mixer: Box<ProjectResourcePublicationOutcome>,
        source: Box<ProjectResourcePublicationError>,
    },
    NativeClose(IdeNativeCloseFailure),
    NativeCloseAndReopen {
        close: IdeNativeCloseFailure,
        reopen: Box<IdeProjectOpenError>,
    },
    ReopenAfterPreparation {
        preparation: Box<Self>,
        reopen: Box<IdeProjectOpenError>,
    },
    ReopenAfterPublication {
        outcome: Box<ProjectResourcePublicationOutcome>,
        source: Box<IdeProjectOpenError>,
    },
    PublicationAndReopen {
        publication: Box<Self>,
        reopen: Box<IdeProjectOpenError>,
    },
}

impl IdeNativeFilterEditError {
    #[must_use]
    pub fn publication_committed(&self) -> bool {
        match self {
            Self::Publication { source, .. } => source.published(),
            Self::ReopenAfterPublication { .. } => true,
            Self::PublicationAndReopen { publication, .. }
            | Self::ReopenAfterPreparation {
                preparation: publication,
                ..
            } => publication.publication_committed(),
            Self::InvalidIdentity
            | Self::CopyRequiresDistinctChains
            | Self::TrackUnavailable
            | Self::ChainUnavailable
            | Self::MixerSave(_)
            | Self::Device(_)
            | Self::Serialization(_)
            | Self::MixerPublication(_)
            | Self::NativeClose(_)
            | Self::NativeCloseAndReopen { .. } => false,
        }
    }
}

impl fmt::Display for IdeNativeFilterEditError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidIdentity => formatter.write_str("native device identity is invalid"),
            Self::CopyRequiresDistinctChains => {
                formatter.write_str("a native device copy target must be in another chain")
            }
            Self::TrackUnavailable => formatter.write_str("native device track is unavailable"),
            Self::ChainUnavailable => formatter.write_str("native device chain is unavailable"),
            Self::MixerSave(source) => write!(
                formatter,
                "live mixer state could not be preserved: {source}"
            ),
            Self::Device(source) | Self::Serialization(source) => source.fmt(formatter),
            Self::MixerPublication(source) => write!(
                formatter,
                "live mixer state could not be published: {source}"
            ),
            Self::Publication { mixer, source } if mixer.changed() => write!(
                formatter,
                "live mixer was preserved in project revision {} but native device publication failed: {source}",
                mixer.project_revision()
            ),
            Self::Publication { source, .. } => source.fmt(formatter),
            Self::NativeClose(source) => write!(
                formatter,
                "native playback did not close cleanly before editing native devices: {source:?}"
            ),
            Self::NativeCloseAndReopen { close, reopen } => write!(
                formatter,
                "native playback did not close cleanly before editing native devices ({close:?}) and authoritative playback could not be reopened: {reopen}"
            ),
            Self::ReopenAfterPreparation {
                preparation,
                reopen,
            } => write!(
                formatter,
                "native device edit was refused ({preparation}) and authoritative playback could not be reopened: {reopen}"
            ),
            Self::ReopenAfterPublication { outcome, source } => write!(
                formatter,
                "native device edit committed as project revision {}, but playback could not be reopened: {source}",
                outcome.project_revision()
            ),
            Self::PublicationAndReopen {
                publication,
                reopen,
            } => write!(
                formatter,
                "native device publication failed ({publication}) and authoritative playback could not be reopened: {reopen}"
            ),
        }
    }
}

impl Error for IdeNativeFilterEditError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::MixerSave(source) => Some(source),
            Self::Device(source) | Self::Serialization(source) => Some(source),
            Self::MixerPublication(source) | Self::Publication { source, .. } => Some(source),
            Self::ReopenAfterPreparation { preparation, .. }
            | Self::PublicationAndReopen {
                publication: preparation,
                ..
            } => Some(preparation),
            Self::ReopenAfterPublication { source, .. } => Some(source),
            Self::InvalidIdentity
            | Self::CopyRequiresDistinctChains
            | Self::TrackUnavailable
            | Self::ChainUnavailable
            | Self::NativeClose(_)
            | Self::NativeCloseAndReopen { .. } => None,
        }
    }
}

/// Why a Runtime native-device update could not be bound to the exact verified
/// device-chain authority in an open project.
///
/// The update carries state only. This preparation therefore refuses any
/// source-chain drift instead of reconstructing a chain or accepting unknown
/// extension semantics from the external artifact.
#[derive(Debug)]
pub enum IdeRuntimeNativeDeviceUpdatePreparationError {
    ProjectSnapshotUnavailable,
    DeviceChainResourceMissing,
    DeviceChainResourceAmbiguous,
    DeviceChainResourceRoleMismatch,
    SourceChainDigestMismatch,
    SourceChainNotCanonical,
    SourceChainUnavailable,
    SourceChainIdentityMismatch,
    SourceChainProjectMismatch,
    SourceChainTrackMismatch,
    DeviceCountMismatch,
    DeviceIdentityMismatch,
    DeviceTypeMismatch,
    DeviceVersionMismatch,
    DeviceStateKindMismatch,
    CapacityUnavailable,
    Storage(StorageError),
    Serialization(DeviceChainError),
    Device(DeviceChainError),
    MixerSave(Box<IdeProjectSaveError>),
}

impl fmt::Display for IdeRuntimeNativeDeviceUpdatePreparationError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::ProjectSnapshotUnavailable => {
                formatter.write_str("running playback exposes no verified project snapshot")
            }
            Self::DeviceChainResourceMissing => {
                formatter.write_str("the Runtime native-device update targets no device-chain resource in the open project")
            }
            Self::DeviceChainResourceAmbiguous => formatter.write_str(
                "the Runtime native-device update targets an ambiguous device-chain resource",
            ),
            Self::DeviceChainResourceRoleMismatch => formatter.write_str(
                "the Runtime native-device update target is not a device-chain resource",
            ),
            Self::SourceChainDigestMismatch => formatter.write_str(
                "the Runtime native-device update does not match the exact source device-chain resource",
            ),
            Self::SourceChainNotCanonical => formatter.write_str(
                "the source device-chain resource is not canonical and cannot accept a Runtime update",
            ),
            Self::SourceChainUnavailable => formatter.write_str(
                "the Runtime native-device update targets a device chain unavailable to active playback",
            ),
            Self::SourceChainIdentityMismatch => formatter.write_str(
                "the Runtime native-device update does not match the source device-chain identity",
            ),
            Self::SourceChainProjectMismatch => formatter.write_str(
                "the Runtime native-device update does not match the source device-chain project",
            ),
            Self::SourceChainTrackMismatch => formatter.write_str(
                "the Runtime native-device update does not match the source device-chain track",
            ),
            Self::DeviceCountMismatch => formatter.write_str(
                "the Runtime native-device update does not match the source device count",
            ),
            Self::DeviceIdentityMismatch => formatter.write_str(
                "the Runtime native-device update does not match a source device identity",
            ),
            Self::DeviceTypeMismatch => formatter.write_str(
                "the Runtime native-device update does not match a source device type",
            ),
            Self::DeviceVersionMismatch => formatter.write_str(
                "the Runtime native-device update does not match a source device version",
            ),
            Self::DeviceStateKindMismatch => formatter.write_str(
                "the Runtime native-device update does not match a source device state kind",
            ),
            Self::CapacityUnavailable => {
                formatter.write_str("native-device update preparation capacity is unavailable")
            }
            Self::Storage(source) => source.fmt(formatter),
            Self::Serialization(source) | Self::Device(source) => source.fmt(formatter),
            Self::MixerSave(source) => {
                write!(formatter, "live mixer state could not be preserved: {source}")
            }
        }
    }
}

impl Error for IdeRuntimeNativeDeviceUpdatePreparationError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Storage(source) => Some(source),
            Self::Serialization(source) | Self::Device(source) => Some(source),
            Self::MixerSave(source) => Some(source.as_ref()),
            Self::ProjectSnapshotUnavailable
            | Self::DeviceChainResourceMissing
            | Self::DeviceChainResourceAmbiguous
            | Self::DeviceChainResourceRoleMismatch
            | Self::SourceChainDigestMismatch
            | Self::SourceChainNotCanonical
            | Self::SourceChainUnavailable
            | Self::SourceChainIdentityMismatch
            | Self::SourceChainProjectMismatch
            | Self::SourceChainTrackMismatch
            | Self::DeviceCountMismatch
            | Self::DeviceIdentityMismatch
            | Self::DeviceTypeMismatch
            | Self::DeviceVersionMismatch
            | Self::DeviceStateKindMismatch
            | Self::CapacityUnavailable => None,
        }
    }
}

/// Publication failure after a Runtime native-device update has been bound to
/// a verified source chain and the current mixer save plan.
#[derive(Debug)]
pub enum IdeRuntimeNativeDeviceUpdatePublicationError {
    Mixer(Box<ProjectResourcePublicationError>),
    DeviceChain {
        mixer: Box<ProjectResourcePublicationOutcome>,
        source: Box<ProjectResourcePublicationError>,
    },
}

impl IdeRuntimeNativeDeviceUpdatePublicationError {
    #[must_use]
    pub fn publication_committed(&self) -> bool {
        match self {
            Self::Mixer(source) => source.published(),
            Self::DeviceChain { mixer, source } => mixer.changed() || source.published(),
        }
    }
}

impl fmt::Display for IdeRuntimeNativeDeviceUpdatePublicationError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Mixer(source) if source.published() => write!(
                formatter,
                "live mixer preservation may have committed with incomplete project verification or recovery: {source}"
            ),
            Self::Mixer(source) => {
                write!(
                    formatter,
                    "live mixer state could not be preserved: {source}"
                )
            }
            Self::DeviceChain { source, .. } if source.published() => write!(
                formatter,
                "Runtime native-device update may have committed with incomplete project verification or recovery: {source}"
            ),
            Self::DeviceChain { mixer, source } if mixer.changed() => write!(
                formatter,
                "live mixer state was preserved in project revision {} but the Runtime native-device update failed: {source}",
                mixer.project_revision()
            ),
            Self::DeviceChain { source, .. } => source.fmt(formatter),
        }
    }
}

impl Error for IdeRuntimeNativeDeviceUpdatePublicationError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Mixer(source) | Self::DeviceChain { source, .. } => Some(source.as_ref()),
        }
    }
}

#[derive(Debug)]
pub enum IdeAutomationTakePublicationError {
    Mixer(Box<ProjectResourcePublicationError>),
    Take {
        mixer: Box<ProjectResourcePublicationOutcome>,
        source: Box<ProjectResourcePublicationError>,
    },
}

impl IdeAutomationTakePublicationError {
    #[must_use]
    pub const fn take_published(&self) -> bool {
        match self {
            Self::Mixer(_) => false,
            Self::Take { source, .. } => source.published(),
        }
    }
}

impl fmt::Display for IdeAutomationTakePublicationError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Mixer(source) if source.published() => write!(
                formatter,
                "live mixer was preserved, but its project transaction cleanup is incomplete: {source}"
            ),
            Self::Mixer(source) => write!(
                formatter,
                "live mixer could not be preserved before changing automation takes: {source}"
            ),
            Self::Take { source, .. } if source.published() => write!(
                formatter,
                "automation take change committed, but project verification or transaction recovery is incomplete: {source}"
            ),
            Self::Take { mixer, source } if mixer.changed() => write!(
                formatter,
                "live mixer was preserved in project revision {} but the automation take change failed: {source}",
                mixer.project_revision()
            ),
            Self::Take { source, .. } => source.fmt(formatter),
        }
    }
}

impl Error for IdeAutomationTakePublicationError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Mixer(source) | Self::Take { source, .. } => Some(source),
        }
    }
}

#[derive(Debug)]
pub enum IdeAutomationTakeCreationError {
    InvalidName,
    InvalidTargetIdentity,
    MixerSave(Box<IdeProjectSaveError>),
    Storage(StorageError),
    MixerDocument(PlaybackDocumentLoadError),
    Serialization(AutomationTakeAdditionSerializationError),
    CapacityUnavailable,
    Publication(Box<IdeAutomationTakePublicationError>),
    NativeClose(IdeNativeCloseFailure),
    NativeCloseAndReopen {
        close: IdeNativeCloseFailure,
        reopen: Box<IdeProjectOpenError>,
    },
    ReopenAfterPreparation {
        preparation: Box<IdeAutomationTakeCreationError>,
        reopen: Box<IdeProjectOpenError>,
    },
    ReopenAfterPublication {
        outcome: Box<ProjectResourcePublicationOutcome>,
        source: Box<IdeProjectOpenError>,
    },
    PublicationAndReopen {
        publication: Box<IdeAutomationTakePublicationError>,
        reopen: Box<IdeProjectOpenError>,
    },
}

impl IdeAutomationTakeCreationError {
    #[must_use]
    pub const fn publication_committed(&self) -> bool {
        match self {
            Self::Publication(source) => source.take_published(),
            Self::ReopenAfterPublication { .. } => true,
            Self::PublicationAndReopen { publication, .. } => publication.take_published(),
            _ => false,
        }
    }
}

impl fmt::Display for IdeAutomationTakeCreationError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidName => {
                formatter.write_str("automation take name must contain 1 through 120 characters")
            }
            Self::InvalidTargetIdentity => {
                formatter.write_str("the automation target identity is empty")
            }
            Self::MixerSave(source) => {
                write!(
                    formatter,
                    "live mixer state could not be preserved: {source}"
                )
            }
            Self::Storage(source) => source.fmt(formatter),
            Self::MixerDocument(source) => source.fmt(formatter),
            Self::Serialization(source) => source.fmt(formatter),
            Self::CapacityUnavailable => {
                formatter.write_str("automation take capacity is unavailable")
            }
            Self::Publication(source) => source.fmt(formatter),
            Self::NativeClose(source) => write!(
                formatter,
                "native playback did not close cleanly before adding the automation take: {source:?}"
            ),
            Self::NativeCloseAndReopen { close, reopen } => write!(
                formatter,
                "native playback did not close cleanly before adding the automation take ({close:?}) and the unchanged project could not be reopened ({reopen})"
            ),
            Self::ReopenAfterPreparation {
                preparation,
                reopen,
            } => write!(
                formatter,
                "automation take preparation failed ({preparation}) and the project could not be reopened ({reopen})"
            ),
            Self::ReopenAfterPublication { outcome, source } => write!(
                formatter,
                "automation take {} was added in project revision {} but the project could not be reopened: {source}",
                outcome.resource_id(),
                outcome.project_revision()
            ),
            Self::PublicationAndReopen {
                publication,
                reopen,
            } if publication.take_published() => write!(
                formatter,
                "automation take committed with incomplete verification or recovery ({publication}) and the project could not be reopened ({reopen})"
            ),
            Self::PublicationAndReopen {
                publication,
                reopen,
            } => write!(
                formatter,
                "automation take publication failed ({publication}) and the project could not be reopened ({reopen})"
            ),
        }
    }
}

impl Error for IdeAutomationTakeCreationError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::MixerSave(source) => Some(source.as_ref()),
            Self::Storage(source) => Some(source),
            Self::MixerDocument(source) => Some(source),
            Self::Serialization(source) => Some(source),
            Self::Publication(source) => Some(source.as_ref()),
            Self::NativeCloseAndReopen { reopen, .. } => Some(reopen.as_ref()),
            Self::ReopenAfterPreparation { preparation, .. } => Some(preparation.as_ref()),
            Self::ReopenAfterPublication { source, .. } => Some(source.as_ref()),
            Self::PublicationAndReopen { publication, .. } => Some(publication.as_ref()),
            Self::InvalidName
            | Self::InvalidTargetIdentity
            | Self::CapacityUnavailable
            | Self::NativeClose(_) => None,
        }
    }
}

