    #[allow(
        clippy::too_many_lines,
        reason = "freeze must retain verified source authority, render from the prepared session, and serialize one complete candidate before publication"
    )]
    fn prepare_audio_track_freeze(
        application: &DesktopIdeApplication,
        recovery: &DesktopPlaybackRecovery,
        track_id: &str,
    ) -> Result<IdeAudioTrackFreezePlan, IdeAudioTrackFreezeError> {
        if track_id.is_empty() {
            return Err(IdeAudioTrackFreezeError::InvalidTrackIdentity);
        }
        let mixer = Self::prepare_mixer_save(application, recovery)
            .map_err(|source| IdeAudioTrackFreezeError::MixerSave(Box::new(source)))?;
        let prepared = recovery.prepared_project().ok_or_else(|| {
            IdeAudioTrackFreezeError::MixerSave(Box::new(
                IdeProjectSaveError::ProjectSnapshotUnavailable,
            ))
        })?;
        let package = prepared.package();
        let descriptor = package
            .manifest()
            .resources()
            .iter()
            .find(|descriptor| descriptor.id() == track_id)
            .ok_or(IdeAudioTrackFreezeError::TrackResourceMissing)?;
        if descriptor.role() != ResourceRole::Track {
            return Err(IdeAudioTrackFreezeError::TrackResourceRoleMismatch);
        }
        let source_track = package
            .read_resource(track_id)
            .map_err(IdeAudioTrackFreezeError::Storage)?;
        let (project, _, _, media) = prepared.session().parts();
        if !project.is_audio_track(track_id) {
            return Err(IdeAudioTrackFreezeError::TrackResourceRoleMismatch);
        }
        let clip_ids = project
            .audio_track_clip_ids(track_id)
            .ok_or(IdeAudioTrackFreezeError::TrackResourceRoleMismatch)?;
        let mut source_clips = Vec::new();
        source_clips
            .try_reserve_exact(clip_ids.len())
            .map_err(|_| IdeAudioTrackFreezeError::CapacityUnavailable)?;
        for clip_id in clip_ids {
            let descriptor = package
                .manifest()
                .resources()
                .iter()
                .find(|descriptor| descriptor.id() == clip_id)
                .ok_or(IdeAudioTrackFreezeError::ClipResourceMissing)?;
            if descriptor.role() != ResourceRole::Clip {
                return Err(IdeAudioTrackFreezeError::ClipResourceRoleMismatch);
            }
            source_clips.push(
                package
                    .read_resource(clip_id)
                    .map_err(IdeAudioTrackFreezeError::Storage)?,
            );
        }
        let mut arrangements = package
            .manifest()
            .resources()
            .iter()
            .filter(|descriptor| descriptor.role() == ResourceRole::Arrangement);
        let arrangement_descriptor = arrangements
            .next()
            .ok_or(IdeAudioTrackFreezeError::ArrangementResourceMissing)?;
        if arrangements.next().is_some() {
            return Err(IdeAudioTrackFreezeError::ArrangementResourceAmbiguous);
        }
        let source_arrangement = package
            .read_resource(arrangement_descriptor.id())
            .map_err(IdeAudioTrackFreezeError::Storage)?;
        let mut chains = prepared
            .device_chains()
            .iter()
            .filter(|chain| chain.track_id() == track_id);
        let device_chain = if let Some(chain) = chains.next() {
            let descriptor = package
                .manifest()
                .resources()
                .iter()
                .find(|descriptor| descriptor.id() == chain.id())
                .ok_or(IdeAudioTrackFreezeError::DeviceChainResourceMissing)?;
            if descriptor.role() != ResourceRole::DeviceChain {
                return Err(IdeAudioTrackFreezeError::DeviceChainResourceMissing);
            }
            Some(AudioTrackFreezeDeviceChain::new(
                chain.id(),
                descriptor.sha256(),
            ))
        } else {
            None
        };
        if chains.next().is_some() {
            return Err(IdeAudioTrackFreezeError::DeviceChainAmbiguous);
        }
        let rendered = render_prepared_audio_track_pre_fader_for_freeze(
            prepared,
            track_id,
            OfflineExportSpec {
                block_frames: application.config.maximum_block_frames(),
            },
        )
        .map_err(|source| IdeAudioTrackFreezeError::Render(Box::new(source)))?;
        let rendered_frame_count = u64::try_from(rendered.frame_count())
            .map_err(|_| IdeAudioTrackFreezeError::CapacityUnavailable)?;
        let rendered_sample =
            encode_float_wav(&rendered).map_err(IdeAudioTrackFreezeError::Sample)?;
        let frozen_asset_id = uuid::Uuid::new_v4().to_string();
        let frozen_clip_id = uuid::Uuid::new_v4().to_string();
        let frozen_placement_id = uuid::Uuid::new_v4().to_string();
        let freeze_state_id = uuid::Uuid::new_v4().to_string();
        let mut assets = Vec::new();
        assets
            .try_reserve_exact(media.asset_count())
            .map_err(|_| IdeAudioTrackFreezeError::CapacityUnavailable)?;
        assets.extend(media.media_asset_facts());
        let source_clip_bytes = source_clips.iter().map(Vec::as_slice).collect::<Vec<_>>();
        let frozen_clip_name = project
            .track_name(track_id)
            .ok_or(IdeAudioTrackFreezeError::TrackResourceMissing)?;
        let documents = serialize_audio_track_freeze(
            project,
            &assets,
            &source_track,
            &source_clip_bytes,
            &source_arrangement,
            track_id,
            &frozen_asset_id,
            rendered_frame_count,
            &frozen_clip_id,
            &frozen_placement_id,
            &freeze_state_id,
            frozen_clip_name,
            device_chain,
            application.config.project_limits.session.documents,
        )
        .map_err(IdeAudioTrackFreezeError::Serialization)?;
        let rendered_sample_byte_length = u64::try_from(rendered_sample.len())
            .map_err(|_| IdeAudioTrackFreezeError::CapacityUnavailable)?;
        let rendered_sample_sha256 = format!("{:x}", Sha256::digest(&rendered_sample));
        let history_authority = IdeTrackFreezeHistoryAuthority::try_new(
            track_id,
            documents.freeze_state(),
            &rendered_sample_sha256,
            rendered_sample_byte_length,
        )
        .map_err(|source| IdeAudioTrackFreezeError::HistoryAuthority(Box::new(source)))?;
        Ok(IdeAudioTrackFreezePlan {
            mixer,
            documents,
            rendered_sample,
            history_authority,
        })
    }

    fn prepare_audio_track_unfreeze(
        application: &DesktopIdeApplication,
        recovery: &DesktopPlaybackRecovery,
        track_id: &str,
    ) -> Result<IdeAudioTrackUnfreezePlan, IdeAudioTrackUnfreezeError> {
        if track_id.is_empty() {
            return Err(IdeAudioTrackUnfreezeError::InvalidTrackIdentity);
        }
        let mixer = Self::prepare_mixer_save(application, recovery)
            .map_err(|source| IdeAudioTrackUnfreezeError::MixerSave(Box::new(source)))?;
        let prepared = recovery.prepared_project().ok_or_else(|| {
            IdeAudioTrackUnfreezeError::MixerSave(Box::new(
                IdeProjectSaveError::ProjectSnapshotUnavailable,
            ))
        })?;
        let package = prepared.package();
        let descriptor = package
            .manifest()
            .resources()
            .iter()
            .find(|descriptor| descriptor.id() == track_id)
            .ok_or(IdeAudioTrackUnfreezeError::TrackResourceMissing)?;
        if descriptor.role() != ResourceRole::Track {
            return Err(IdeAudioTrackUnfreezeError::TrackResourceRoleMismatch);
        }
        let source_track = package
            .read_resource(track_id)
            .map_err(IdeAudioTrackUnfreezeError::Storage)?;
        let (project, _, _, media) = prepared.session().parts();
        if !project.is_audio_track(track_id) {
            return Err(IdeAudioTrackUnfreezeError::TrackResourceRoleMismatch);
        }
        let mut arrangements = package
            .manifest()
            .resources()
            .iter()
            .filter(|descriptor| descriptor.role() == ResourceRole::Arrangement);
        let arrangement = arrangements
            .next()
            .ok_or(IdeAudioTrackUnfreezeError::ArrangementResourceMissing)?;
        if arrangements.next().is_some() {
            return Err(IdeAudioTrackUnfreezeError::ArrangementResourceAmbiguous);
        }
        let source_arrangement = package
            .read_resource(arrangement.id())
            .map_err(IdeAudioTrackUnfreezeError::Storage)?;
        let mut freeze_states = Vec::new();
        for descriptor in package
            .manifest()
            .resources()
            .iter()
            .filter(|descriptor| descriptor.role() == ResourceRole::FreezeState)
        {
            let bytes = package
                .read_resource(descriptor.id())
                .map_err(IdeAudioTrackUnfreezeError::Storage)?;
            let value: serde_json::Value = serde_json::from_slice(&bytes)
                .map_err(|_| IdeAudioTrackUnfreezeError::FreezeStateInvalid)?;
            if value["track_id"].as_str() == Some(track_id) {
                freeze_states.push(bytes);
            }
        }
        if freeze_states.is_empty() {
            return Err(IdeAudioTrackUnfreezeError::FreezeStateMissing);
        }
        if freeze_states.len() != 1 {
            return Err(IdeAudioTrackUnfreezeError::FreezeStateInvalid);
        }
        let mut assets = Vec::new();
        assets
            .try_reserve_exact(media.asset_count())
            .map_err(|_| IdeAudioTrackUnfreezeError::CapacityUnavailable)?;
        assets.extend(media.media_asset_facts());
        let documents = serialize_audio_track_unfreeze(
            project,
            &assets,
            &source_track,
            &source_arrangement,
            &freeze_states[0],
            track_id,
            application.config.project_limits.session.documents,
        )
        .map_err(IdeAudioTrackUnfreezeError::Serialization)?;
        let frozen_asset = package
            .manifest()
            .assets()
            .iter()
            .find(|asset| asset.id() == documents.frozen_asset_id())
            .ok_or(IdeAudioTrackUnfreezeError::FreezeStateInvalid)?;
        let history_authority = Self::prepare_audio_track_unfreeze_history_authority(
            track_id,
            &freeze_states[0],
            frozen_asset.sha256(),
            frozen_asset.byte_length(),
        )?;
        Ok(IdeAudioTrackUnfreezePlan {
            mixer,
            documents,
            history_authority,
        })
    }

    fn prepare_audio_track_flatten(
        application: &DesktopIdeApplication,
        recovery: &DesktopPlaybackRecovery,
        track_id: &str,
    ) -> Result<IdeAudioTrackFlattenPlan, IdeAudioTrackFlattenError> {
        if track_id.is_empty() {
            return Err(IdeAudioTrackFlattenError::InvalidTrackIdentity);
        }
        let mixer = Self::prepare_mixer_save(application, recovery)
            .map_err(|source| IdeAudioTrackFlattenError::MixerSave(Box::new(source)))?;
        let prepared = recovery.prepared_project().ok_or_else(|| {
            IdeAudioTrackFlattenError::MixerSave(Box::new(
                IdeProjectSaveError::ProjectSnapshotUnavailable,
            ))
        })?;
        let package = prepared.package();
        let descriptor = package
            .manifest()
            .resources()
            .iter()
            .find(|descriptor| descriptor.id() == track_id)
            .ok_or(IdeAudioTrackFlattenError::TrackResourceMissing)?;
        if descriptor.role() != ResourceRole::Track {
            return Err(IdeAudioTrackFlattenError::TrackResourceRoleMismatch);
        }
        let (project, _, _, _) = prepared.session().parts();
        if !project.is_audio_track(track_id) {
            return Err(IdeAudioTrackFlattenError::TrackResourceRoleMismatch);
        }
        let freeze_state_count = package
            .manifest()
            .resources()
            .iter()
            .filter(|descriptor| descriptor.role() == ResourceRole::FreezeState)
            .count();
        let mut freeze_states = Vec::new();
        freeze_states
            .try_reserve_exact(freeze_state_count)
            .map_err(|_| IdeAudioTrackFlattenError::CapacityUnavailable)?;
        for descriptor in package
            .manifest()
            .resources()
            .iter()
            .filter(|descriptor| descriptor.role() == ResourceRole::FreezeState)
        {
            let bytes = package
                .read_resource(descriptor.id())
                .map_err(IdeAudioTrackFlattenError::Storage)?;
            let state = TrackFreezeState::parse(&bytes)
                .map_err(|_| IdeAudioTrackFlattenError::FreezeStateInvalid)?;
            if state.track_id() == track_id {
                let mut state_id = String::new();
                state_id
                    .try_reserve_exact(descriptor.id().len())
                    .map_err(|_| IdeAudioTrackFlattenError::CapacityUnavailable)?;
                state_id.push_str(descriptor.id());
                freeze_states.push((state_id, state));
            }
        }
        let (freeze_state_id, state) = match freeze_states.as_slice() {
            [] => return Err(IdeAudioTrackFlattenError::FreezeStateMissing),
            [state] => state,
            _ => return Err(IdeAudioTrackFlattenError::FreezeStateInvalid),
        };
        if state.id() != freeze_state_id
            || state.project_id() != package.manifest().project_id()
            || state.track_id() != track_id
        {
            return Err(IdeAudioTrackFlattenError::FreezeStateInvalid);
        }
        if !state.has_complete_rendered_authority() {
            return Err(IdeAudioTrackFlattenError::FreezeStateIncomplete);
        }
        let mut planned_track_id = String::new();
        planned_track_id
            .try_reserve_exact(track_id.len())
            .map_err(|_| IdeAudioTrackFlattenError::CapacityUnavailable)?;
        planned_track_id.push_str(track_id);
        let mut planned_freeze_state_id = String::new();
        planned_freeze_state_id
            .try_reserve_exact(freeze_state_id.len())
            .map_err(|_| IdeAudioTrackFlattenError::CapacityUnavailable)?;
        planned_freeze_state_id.push_str(freeze_state_id);
        Ok(IdeAudioTrackFlattenPlan {
            mixer,
            track_id: planned_track_id,
            freeze_state_id: planned_freeze_state_id,
        })
    }

    fn prepare_audio_track_unfreeze_history_authority(
        track_id: &str,
        freeze_state: &[u8],
        frozen_asset_sha256: &str,
        frozen_asset_byte_length: u64,
    ) -> Result<Option<IdeTrackFreezeHistoryAuthority>, IdeAudioTrackUnfreezeError> {
        let state = TrackFreezeState::parse(freeze_state)
            .map_err(|_| IdeAudioTrackUnfreezeError::FreezeStateInvalid)?;
        if !state.has_complete_rendered_authority() {
            return Ok(None);
        }
        IdeTrackFreezeHistoryAuthority::try_new(
            track_id,
            freeze_state,
            frozen_asset_sha256,
            frozen_asset_byte_length,
        )
        .map(Some)
        .map_err(|source| IdeAudioTrackUnfreezeError::HistoryAuthority(Box::new(source)))
    }

    fn prepare_audio_track_unfreeze_history(
        application: &DesktopIdeApplication,
        recovery: &DesktopPlaybackRecovery,
        authority: &IdeTrackFreezeHistoryAuthority,
    ) -> Result<IdeAudioTrackUnfreezePlan, IdeResourceRestoreError> {
        let plan = Self::prepare_audio_track_unfreeze(application, recovery, authority.track_id())
            .map_err(|source| IdeResourceRestoreError::AudioTrackUnfreeze(Box::new(source)))?;
        if plan
            .history_authority()
            .is_none_or(|candidate| candidate != authority)
        {
            return Err(IdeResourceRestoreError::CandidateInvalid(Box::new(
                IdeTrackFreezeHistoryAuthorityError::StateMismatch,
            )));
        }
        Ok(plan)
    }

    #[allow(
        clippy::too_many_lines,
        reason = "reactivation authenticates the live source, retained authority, and durable asset before one atomic structural publication"
    )]
    fn prepare_audio_track_freeze_reactivation(
        application: &DesktopIdeApplication,
        recovery: &DesktopPlaybackRecovery,
        authority: &IdeTrackFreezeHistoryAuthority,
    ) -> Result<IdeAudioTrackFreezeReactivationPlan, IdeResourceRestoreError> {
        let mixer = Self::prepare_mixer_save(application, recovery)
            .map_err(|source| IdeResourceRestoreError::MixerSave(Box::new(source)))?;
        let prepared = recovery.prepared_project().ok_or_else(|| {
            IdeResourceRestoreError::MixerSave(Box::new(
                IdeProjectSaveError::ProjectSnapshotUnavailable,
            ))
        })?;
        let package = prepared.package();
        let descriptor = package
            .manifest()
            .resources()
            .iter()
            .find(|descriptor| descriptor.id() == authority.track_id())
            .ok_or(IdeResourceRestoreError::ResourceMissing)?;
        if descriptor.role() != ResourceRole::Track {
            return Err(IdeResourceRestoreError::CandidateInvalid(Box::new(
                IdeTrackFreezeHistoryAuthorityError::StateMismatch,
            )));
        }
        let source_track = package
            .read_resource(authority.track_id())
            .map_err(IdeResourceRestoreError::Storage)?;
        let (project, _, _, media) = prepared.session().parts();
        let clip_ids = project
            .audio_track_clip_ids(authority.track_id())
            .ok_or_else(|| {
                IdeResourceRestoreError::CandidateInvalid(Box::new(
                    IdeTrackFreezeHistoryAuthorityError::StateMismatch,
                ))
            })?;
        let mut source_clips = Vec::new();
        source_clips
            .try_reserve_exact(clip_ids.len())
            .map_err(|_| IdeResourceRestoreError::CapacityUnavailable)?;
        for clip_id in clip_ids {
            let descriptor = package
                .manifest()
                .resources()
                .iter()
                .find(|descriptor| descriptor.id() == clip_id)
                .ok_or(IdeResourceRestoreError::ResourceMissing)?;
            if descriptor.role() != ResourceRole::Clip {
                return Err(IdeResourceRestoreError::CandidateInvalid(Box::new(
                    IdeTrackFreezeHistoryAuthorityError::StateMismatch,
                )));
            }
            source_clips.push(
                package
                    .read_resource(clip_id)
                    .map_err(IdeResourceRestoreError::Storage)?,
            );
        }
        let mut arrangements = package
            .manifest()
            .resources()
            .iter()
            .filter(|descriptor| descriptor.role() == ResourceRole::Arrangement);
        let arrangement_descriptor = arrangements
            .next()
            .ok_or(IdeResourceRestoreError::ResourceMissing)?;
        if arrangements.next().is_some() {
            return Err(IdeResourceRestoreError::CandidateInvalid(Box::new(
                IdeTrackFreezeHistoryAuthorityError::StateMismatch,
            )));
        }
        let source_arrangement = package
            .read_resource(arrangement_descriptor.id())
            .map_err(IdeResourceRestoreError::Storage)?;
        let mut assets = Vec::new();
        assets
            .try_reserve_exact(media.asset_count())
            .map_err(|_| IdeResourceRestoreError::CapacityUnavailable)?;
        assets.extend(media.media_asset_facts());
        let source_clip_bytes = source_clips.iter().map(Vec::as_slice).collect::<Vec<_>>();
        let documents = serialize_audio_track_freeze_reactivation(
            project,
            &assets,
            &source_track,
            &source_clip_bytes,
            &source_arrangement,
            authority.freeze_state(),
            authority.track_id(),
            application.config.project_limits.session.documents,
        )
        .map_err(|source| IdeResourceRestoreError::CandidateInvalid(Box::new(source)))?;
        let frozen_asset = package
            .manifest()
            .assets()
            .iter()
            .find(|asset| asset.id() == documents.frozen_asset_id())
            .ok_or_else(|| {
                IdeResourceRestoreError::CandidateInvalid(Box::new(
                    IdeTrackFreezeHistoryAuthorityError::StateMismatch,
                ))
            })?;
        if frozen_asset.sha256() != authority.frozen_asset_sha256()
            || frozen_asset.byte_length() != authority.frozen_asset_byte_length()
        {
            return Err(IdeResourceRestoreError::CandidateInvalid(Box::new(
                IdeTrackFreezeHistoryAuthorityError::StateMismatch,
            )));
        }
        Ok(IdeAudioTrackFreezeReactivationPlan {
            mixer,
            documents,
            frozen_asset_sha256: authority.frozen_asset_sha256().to_owned(),
            frozen_asset_byte_length: authority.frozen_asset_byte_length(),
        })
    }

    #[allow(
        clippy::too_many_lines,
        reason = "the complete manifest source inventory makes full track removal refuse partial graph authority"
    )]
    fn prepare_audio_track_content_removal(
        application: &DesktopIdeApplication,
        recovery: &DesktopPlaybackRecovery,
        track_id: &str,
    ) -> Result<IdeAudioTrackContentRemovalPlan, IdeAudioTrackContentRemovalError> {
        if track_id.is_empty() {
            return Err(IdeAudioTrackContentRemovalError::InvalidTrackIdentity);
        }
        let mixer = Self::prepare_mixer_save(application, recovery)
            .map_err(|source| IdeAudioTrackContentRemovalError::MixerSave(Box::new(source)))?;
        let prepared = recovery.prepared_project().ok_or_else(|| {
            IdeAudioTrackContentRemovalError::MixerSave(Box::new(
                IdeProjectSaveError::ProjectSnapshotUnavailable,
            ))
        })?;
        let package = prepared.package();
        let descriptor = package
            .manifest()
            .resources()
            .iter()
            .find(|descriptor| descriptor.id() == track_id)
            .ok_or(IdeAudioTrackContentRemovalError::TrackResourceMissing)?;
        if descriptor.role() != ResourceRole::Track {
            return Err(IdeAudioTrackContentRemovalError::TrackResourceRoleMismatch);
        }
        let track = package
            .read_resource(track_id)
            .map_err(IdeAudioTrackContentRemovalError::Storage)?;
        let (project, compiled_mixer, _, media) = prepared.session().parts();
        if project.structural_track_index(track_id).is_none() {
            return Err(IdeAudioTrackContentRemovalError::TrackResourceMissing);
        }
        let track_slot = compiled_mixer
            .slots()
            .iter()
            .find(|slot| slot.track_id() == track_id);
        let control_mappings = prepared.control_mapping().map_or(0, |mapping| {
            mapping
                .bindings()
                .iter()
                .filter(|binding| {
                    control_binding_references_audio_track(binding, track_id, |send_id| {
                        track_slot.is_some_and(|slot| {
                            slot.sends().iter().any(|send| send.id() == send_id)
                        })
                    })
                })
                .count()
        });
        let recording_metadata = prepared
            .recording_metadata()
            .iter()
            .filter(|metadata| metadata.track_id() == track_id)
            .count();
        if control_mappings != 0 || recording_metadata != 0 {
            return Err(IdeAudioTrackContentRemovalError::ExternalReferences {
                control_mappings,
                recording_metadata,
            });
        }

        let mut assets = Vec::new();
        assets
            .try_reserve_exact(media.asset_count())
            .map_err(|_| IdeAudioTrackContentRemovalError::CapacityUnavailable)?;
        assets.extend(media.media_asset_facts());

        let resources = package.manifest().resources();
        let mut clips = Vec::new();
        let mut scenes = Vec::new();
        let mut automation_ids = Vec::new();
        let mut automation_takes = Vec::new();
        clips
            .try_reserve_exact(resources.len())
            .map_err(|_| IdeAudioTrackContentRemovalError::CapacityUnavailable)?;
        scenes
            .try_reserve_exact(resources.len())
            .map_err(|_| IdeAudioTrackContentRemovalError::CapacityUnavailable)?;
        automation_ids
            .try_reserve_exact(resources.len())
            .map_err(|_| IdeAudioTrackContentRemovalError::CapacityUnavailable)?;
        automation_takes
            .try_reserve_exact(resources.len())
            .map_err(|_| IdeAudioTrackContentRemovalError::CapacityUnavailable)?;
        let mut arrangement = None;
        let mut device_chain_id = None;
        let mut device_chain = None;
        for descriptor in resources {
            match descriptor.role() {
                ResourceRole::Clip => {
                    let bytes = package
                        .read_resource(descriptor.id())
                        .map_err(IdeAudioTrackContentRemovalError::Storage)?;
                    clips.push((descriptor.id().to_owned(), bytes));
                }
                ResourceRole::Scene => {
                    let bytes = package
                        .read_resource(descriptor.id())
                        .map_err(IdeAudioTrackContentRemovalError::Storage)?;
                    scenes.push((descriptor.id().to_owned(), bytes));
                }
                ResourceRole::Arrangement => {
                    if arrangement.is_some() {
                        return Err(IdeAudioTrackContentRemovalError::TrackResourceRoleMismatch);
                    }
                    arrangement = Some(
                        package
                            .read_resource(descriptor.id())
                            .map_err(IdeAudioTrackContentRemovalError::Storage)?,
                    );
                }
                ResourceRole::AutomationTake => {
                    let bytes = package
                        .read_resource(descriptor.id())
                        .map_err(IdeAudioTrackContentRemovalError::Storage)?;
                    automation_ids.push(descriptor.id().to_owned());
                    automation_takes.push((descriptor.id().to_owned(), bytes));
                }
                ResourceRole::DeviceChain => {
                    let bytes = package
                        .read_resource(descriptor.id())
                        .map_err(IdeAudioTrackContentRemovalError::Storage)?;
                    let chain = DeviceChain::parse(&bytes)
                        .map_err(IdeAudioTrackContentRemovalError::Device)?;
                    if chain.track_id() == track_id {
                        if device_chain.is_some() {
                            return Err(IdeAudioTrackContentRemovalError::DeviceChainAmbiguous);
                        }
                        device_chain_id = Some(descriptor.id().to_owned());
                        device_chain = Some(bytes);
                    }
                }
                _ => {}
            }
        }
        let clip_sources = clips
            .iter()
            .map(|(id, bytes)| (id.as_str(), bytes.as_slice()))
            .collect::<Vec<_>>();
        let scene_sources = scenes
            .iter()
            .map(|(id, bytes)| (id.as_str(), bytes.as_slice()))
            .collect::<Vec<_>>();
        let automation_take_ids = automation_ids
            .iter()
            .map(String::as_str)
            .collect::<Vec<_>>();
        let automation_sources = automation_takes
            .iter()
            .map(|(id, bytes)| (id.as_str(), bytes.as_slice()))
            .collect::<Vec<_>>();
        let documents = serialize_audio_track_content_removal(
            project,
            &assets,
            AudioTrackContentRemovalSource {
                track: &track,
                clips: &clip_sources,
                scenes: &scene_sources,
                arrangement: arrangement.as_deref(),
                mixer: &mixer.resource_bytes,
                automation_take_ids: &automation_take_ids,
                automation_takes: &automation_sources,
                device_chain_id: device_chain_id.as_deref(),
                device_chain: device_chain.as_deref(),
            },
            track_id,
            application.config.project_limits.session.documents,
        )
        .map_err(IdeAudioTrackContentRemovalError::Serialization)?;
        Ok(IdeAudioTrackContentRemovalPlan {
            project_path: mixer.project_path,
            expected_project_sha256: mixer.expected_project_sha256,
            documents,
        })
    }

    fn prepare_audio_track_rename(
        application: &DesktopIdeApplication,
        recovery: &DesktopPlaybackRecovery,
        track_id: &str,
        track_name: &str,
    ) -> Result<IdeAudioTrackEditPlan, IdeAudioTrackEditError> {
        let name_length = track_name.chars().count();
        if track_name.trim() != track_name || !(1..=120).contains(&name_length) {
            return Err(IdeAudioTrackEditError::InvalidName);
        }
        Self::prepare_audio_track_edit(
            application,
            recovery,
            track_id,
            |project, source, limits| {
                serialize_audio_track_rename(project, source, track_id, track_name, limits).map_err(
                    |source| match source {
                        AudioTrackRenameSerializationError::InvalidTrackName => {
                            IdeAudioTrackEditError::InvalidName
                        }
                        AudioTrackRenameSerializationError::Document(source) => {
                            IdeAudioTrackEditError::Serialization(source)
                        }
                    },
                )
            },
        )
    }

    fn prepare_routing_bus_rename(
        application: &DesktopIdeApplication,
        recovery: &DesktopPlaybackRecovery,
        track_id: &str,
        track_name: &str,
    ) -> Result<IdeAudioTrackEditPlan, IdeRoutingBusRenameError> {
        let name_length = track_name.chars().count();
        if track_name.trim() != track_name || !(1..=120).contains(&name_length) {
            return Err(IdeRoutingBusRenameError::InvalidName);
        }
        let mixer = Self::prepare_mixer_save(application, recovery)
            .map_err(|source| IdeRoutingBusRenameError::MixerSave(Box::new(source)))?;
        let prepared = recovery.prepared_project().ok_or_else(|| {
            IdeRoutingBusRenameError::MixerSave(Box::new(
                IdeProjectSaveError::ProjectSnapshotUnavailable,
            ))
        })?;
        let package = prepared.package();
        let descriptor = package
            .manifest()
            .resources()
            .iter()
            .find(|descriptor| descriptor.id() == track_id)
            .ok_or(IdeRoutingBusRenameError::TrackResourceMissing)?;
        if descriptor.role() != ResourceRole::Track {
            return Err(IdeRoutingBusRenameError::TrackResourceRoleMismatch);
        }
        let source = package
            .read_resource(track_id)
            .map_err(IdeRoutingBusRenameError::Storage)?;
        let (project, _, _, _) = prepared.session().parts();
        let track_bytes = serialize_routing_bus_rename(
            project,
            &source,
            track_id,
            track_name,
            application.config.project_limits.session.documents,
        )
        .map_err(IdeRoutingBusRenameError::Serialization)?;
        let mut owned_track_id = String::new();
        owned_track_id
            .try_reserve_exact(track_id.len())
            .map_err(|_| IdeRoutingBusRenameError::CapacityUnavailable)?;
        owned_track_id.push_str(track_id);
        Ok(IdeAudioTrackEditPlan {
            mixer,
            track_id: owned_track_id,
            track_bytes,
        })
    }

    fn prepare_mixer_strip_reorder(
        application: &DesktopIdeApplication,
        recovery: &DesktopPlaybackRecovery,
        track_id: &str,
        destination_index: usize,
    ) -> Result<IdeMixerStripReorderPlan, IdeMixerStripReorderError> {
        let mixer = Self::prepare_mixer_save(application, recovery)
            .map_err(|source| IdeMixerStripReorderError::MixerSave(Box::new(source)))?;
        let prepared = recovery.prepared_project().ok_or_else(|| {
            IdeMixerStripReorderError::MixerSave(Box::new(
                IdeProjectSaveError::ProjectSnapshotUnavailable,
            ))
        })?;
        let package = prepared.package();
        let descriptor = package
            .manifest()
            .resources()
            .iter()
            .find(|descriptor| descriptor.id() == track_id)
            .ok_or(IdeMixerStripReorderError::TrackResourceMissing)?;
        if descriptor.role() != ResourceRole::Track {
            return Err(IdeMixerStripReorderError::TrackResourceRoleMismatch);
        }
        let (project, _, _, media) = prepared.session().parts();
        if !project.supports_flat_mixer_strip_reorder() {
            return Err(IdeMixerStripReorderError::TrackResourceRoleMismatch);
        }
        if project.structural_track_index(track_id).is_none() {
            return Err(IdeMixerStripReorderError::TrackResourceMissing);
        }
        let mut assets = Vec::new();
        assets
            .try_reserve_exact(media.asset_count())
            .map_err(|_| IdeMixerStripReorderError::CapacityUnavailable)?;
        assets.extend(media.media_asset_facts());

        let track_descriptors = package
            .manifest()
            .resources()
            .iter()
            .filter(|descriptor| descriptor.role() == ResourceRole::Track)
            .collect::<Vec<_>>();
        let mut source_tracks = Vec::new();
        source_tracks
            .try_reserve_exact(track_descriptors.len())
            .map_err(|_| IdeMixerStripReorderError::CapacityUnavailable)?;
        for descriptor in track_descriptors {
            let mut id = String::new();
            id.try_reserve_exact(descriptor.id().len())
                .map_err(|_| IdeMixerStripReorderError::CapacityUnavailable)?;
            id.push_str(descriptor.id());
            let bytes = package
                .read_resource(descriptor.id())
                .map_err(IdeMixerStripReorderError::Storage)?;
            source_tracks.push((id, bytes));
        }
        let sources = source_tracks
            .iter()
            .map(|(id, bytes)| (id.as_str(), bytes.as_slice()))
            .collect::<Vec<_>>();
        let documents = serialize_mixer_strip_reorder(
            project,
            &assets,
            &sources,
            &mixer.resource_bytes,
            &mixer.resource_id,
            track_id,
            destination_index,
            application.config.project_limits.session.documents,
        )
        .map_err(IdeMixerStripReorderError::Serialization)?;
        Ok(IdeMixerStripReorderPlan { mixer, documents })
    }

    #[allow(
        clippy::too_many_lines,
        reason = "the complete manifest resource inventory is retained explicitly so duplication never infers a partial mutable graph"
    )]
    fn prepare_audio_track_duplication(
        application: &DesktopIdeApplication,
        recovery: &DesktopPlaybackRecovery,
        track_id: &str,
        track_name: &str,
    ) -> Result<IdeAudioTrackDuplicationPlan, IdeAudioTrackDuplicationError> {
        let name_length = track_name.chars().count();
        if track_name.trim() != track_name || !(1..=120).contains(&name_length) {
            return Err(IdeAudioTrackDuplicationError::InvalidName);
        }
        let mixer = Self::prepare_mixer_save(application, recovery)
            .map_err(|source| IdeAudioTrackDuplicationError::MixerSave(Box::new(source)))?;
        let prepared = recovery.prepared_project().ok_or_else(|| {
            IdeAudioTrackDuplicationError::MixerSave(Box::new(
                IdeProjectSaveError::ProjectSnapshotUnavailable,
            ))
        })?;
        let package = prepared.package();
        let source_descriptor = package
            .manifest()
            .resources()
            .iter()
            .find(|descriptor| descriptor.id() == track_id)
            .ok_or(IdeAudioTrackDuplicationError::TrackResourceMissing)?;
        if source_descriptor.role() != ResourceRole::Track {
            return Err(IdeAudioTrackDuplicationError::TrackResourceRoleMismatch);
        }
        let source_track = package
            .read_resource(track_id)
            .map_err(IdeAudioTrackDuplicationError::Storage)?;
        let (project, _, _, media) = prepared.session().parts();
        if project.structural_track_index(track_id).is_none() {
            return Err(IdeAudioTrackDuplicationError::TrackResourceMissing);
        }
        let mut assets = Vec::new();
        assets
            .try_reserve_exact(media.asset_count())
            .map_err(|_| IdeAudioTrackDuplicationError::CapacityUnavailable)?;
        assets.extend(media.media_asset_facts());

        let resources = package.manifest().resources();
        let mut clips = Vec::new();
        let mut scenes = Vec::new();
        let mut automation_ids = Vec::new();
        let mut automation_takes = Vec::new();
        clips
            .try_reserve_exact(resources.len())
            .map_err(|_| IdeAudioTrackDuplicationError::CapacityUnavailable)?;
        scenes
            .try_reserve_exact(resources.len())
            .map_err(|_| IdeAudioTrackDuplicationError::CapacityUnavailable)?;
        automation_ids
            .try_reserve_exact(resources.len())
            .map_err(|_| IdeAudioTrackDuplicationError::CapacityUnavailable)?;
        automation_takes
            .try_reserve_exact(resources.len())
            .map_err(|_| IdeAudioTrackDuplicationError::CapacityUnavailable)?;
        let mut arrangement = None;
        let mut device_chain_id = None;
        let mut device_chain = None;
        for descriptor in resources {
            match descriptor.role() {
                ResourceRole::Clip => {
                    let bytes = package
                        .read_resource(descriptor.id())
                        .map_err(IdeAudioTrackDuplicationError::Storage)?;
                    clips.push((descriptor.id().to_owned(), bytes));
                }
                ResourceRole::Scene => {
                    let bytes = package
                        .read_resource(descriptor.id())
                        .map_err(IdeAudioTrackDuplicationError::Storage)?;
                    scenes.push((descriptor.id().to_owned(), bytes));
                }
                ResourceRole::Arrangement => {
                    if arrangement.is_some() {
                        return Err(IdeAudioTrackDuplicationError::TrackResourceRoleMismatch);
                    }
                    arrangement = Some(
                        package
                            .read_resource(descriptor.id())
                            .map_err(IdeAudioTrackDuplicationError::Storage)?,
                    );
                }
                ResourceRole::AutomationTake => {
                    let bytes = package
                        .read_resource(descriptor.id())
                        .map_err(IdeAudioTrackDuplicationError::Storage)?;
                    automation_ids.push(descriptor.id().to_owned());
                    automation_takes.push((descriptor.id().to_owned(), bytes));
                }
                ResourceRole::DeviceChain => {
                    let bytes = package
                        .read_resource(descriptor.id())
                        .map_err(IdeAudioTrackDuplicationError::Storage)?;
                    let chain = DeviceChain::parse(&bytes)
                        .map_err(IdeAudioTrackDuplicationError::Device)?;
                    if chain.track_id() == track_id {
                        if device_chain.is_some() {
                            return Err(IdeAudioTrackDuplicationError::DeviceChainAmbiguous);
                        }
                        device_chain_id = Some(descriptor.id().to_owned());
                        device_chain = Some(bytes);
                    }
                }
                _ => {}
            }
        }
        let clip_sources = clips
            .iter()
            .map(|(id, bytes)| (id.as_str(), bytes.as_slice()))
            .collect::<Vec<_>>();
        let scene_sources = scenes
            .iter()
            .map(|(id, bytes)| (id.as_str(), bytes.as_slice()))
            .collect::<Vec<_>>();
        let automation_take_ids = automation_ids
            .iter()
            .map(String::as_str)
            .collect::<Vec<_>>();
        let automation_sources = automation_takes
            .iter()
            .map(|(id, bytes)| (id.as_str(), bytes.as_slice()))
            .collect::<Vec<_>>();
        let documents = if project.is_audio_track(track_id) {
            serialize_audio_track_duplication(
                project,
                &assets,
                AudioTrackDuplicationSource {
                    track: &source_track,
                    clips: &clip_sources,
                    scenes: &scene_sources,
                    arrangement: arrangement.as_deref(),
                    mixer: &mixer.resource_bytes,
                    automation_take_ids: &automation_take_ids,
                    automation_takes: &automation_sources,
                    device_chain_id: device_chain_id.as_deref(),
                    device_chain: device_chain.as_deref(),
                },
                track_id,
                track_name,
                application.config.project_limits.session.documents,
                || uuid::Uuid::new_v4().to_string(),
            )
            .map_err(IdeAudioTrackDuplicationError::Serialization)?
        } else {
            serialize_routing_bus_duplication(
                project,
                &assets,
                RoutingBusDuplicationSource {
                    track: &source_track,
                    mixer: &mixer.resource_bytes,
                    automation_take_ids: &automation_take_ids,
                    automation_takes: &automation_sources,
                    device_chain_id: device_chain_id.as_deref(),
                    device_chain: device_chain.as_deref(),
                },
                track_id,
                track_name,
                application.config.project_limits.session.documents,
                || uuid::Uuid::new_v4().to_string(),
            )
            .map_err(IdeAudioTrackDuplicationError::RoutingBusSerialization)?
        };
        Ok(IdeAudioTrackDuplicationPlan { mixer, documents })
    }

