        let package = prepared.package();
        assert!(
            !package
                .manifest()
                .resources()
                .iter()
                .any(|descriptor| descriptor.role() == ResourceRole::Arrangement)
        );
        let mixer = package
            .manifest()
            .resources()
            .iter()
            .find(|descriptor| descriptor.role() == ResourceRole::Mixer)
            .unwrap();
        let mixer_id = mixer.id().to_owned();
